1	use crate::budget::BudgetSummary;
2	use crate::hints::Hint;
3	use crate::kv::KvItem;
4	use crate::provenance::ProvenanceBlock;
5	use crate::recovery::RecoveryHint;
6	use crate::section::{Section, SectionBody};
7	use crate::toon::Value;
8	
9	/// The serialisation format for `AgentResponse::render`.
10	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
11	#[non_exhaustive]
12	pub enum OutputFormat {
13	    /// Plain-text TOON / kv format. Default.
14	    #[default]
15	    Text,
16	    /// Compact JSON object.
17	    Json,
18	}
19	
20	#[derive(Debug, Clone, PartialEq, Eq)]
21	enum RenderTarget {
22	    Unset,
23	    Toon,
24	    Kv,
25	}
26	
27	/// Default per-cell truncation limit used by [`AgentResponse::new`].
28	pub const DEFAULT_TRUNCATE_CELLS: usize = 200;
29	
30	/// Builder for an agent-facing response.
31	#[derive(Debug, Clone)]
32	#[non_exhaustive]
33	pub struct AgentResponse {
34	    /// The TOON list slot: type name, fields, rows, total count, cell cap and truncation hint, kept as the options
35	    /// the renderer validates and renders by reference, so a render never copies the rows. Its `hints` stay empty:
36	    /// the response's hints are appended after the body instead.
37	    toon: crate::toon::ToonOptions,
38	    target: RenderTarget,
39	    single_item: Vec<KvItem>,
40	    /// Sections added with [`section`](Self::section), rendered in insertion order after the `items()` / `kv_items()`
41	    /// slot (when one was set). Empty for every response that predates sections, which renders as it always did.
42	    sections: Vec<Section>,
43	    /// Response-level budget report, set with `budget()`.
44	    budget: Option<BudgetSummary>,
45	    /// Response-level provenance block, set with `provenance()`.
46	    provenance: Option<ProvenanceBlock>,
47	    hints: Vec<Hint>,
48	    recovery: Vec<RecoveryHint>,
49	    is_error: bool,
50	    human_content: Option<String>,
51	}
52	
53	impl AgentResponse {
54	    /// Create a new, empty response for the given type name.
55	    pub fn new(type_name: impl Into<String>) -> Self {
56	        Self {
57	            toon: crate::toon::ToonOptions::new(type_name, Vec::new(), Vec::new()).max_cell_len(DEFAULT_TRUNCATE_CELLS),
58	            target: RenderTarget::Unset,
59	            single_item: Vec::new(),
60	            sections: Vec::new(),
61	            budget: None,
62	            provenance: None,
63	            hints: Vec::new(),
64	            recovery: Vec::new(),
65	            is_error: false,
66	            human_content: None,
67	        }
68	    }
69	
70	    /// Populate the TOON list path.
71	    #[must_use]
72	    pub fn items(mut self, rows: Vec<Vec<Value>>, fields: &[&str]) -> Self {
73	        self.toon.rows = rows;
74	        self.toon.fields = fields.iter().map(|s| (*s).to_string()).collect();
75	        self.target = RenderTarget::Toon;
76	        self
77	    }
78	
79	    /// Set the total available count.
80	    #[must_use]
81	    pub fn total_count(mut self, n: usize) -> Self {
82	        self.toon.total_count = Some(n);
83	        self
84	    }
85	
86	    /// Report a list cut in one call: sets the total count to `outcome.total_before` and, only when something was
87	    /// cut, appends [`TruncationOutcome::hint`](crate::truncation::TruncationOutcome::hint)`(guidance)`, so the
88	    /// `totalCount` and the `help[]` line always describe the same cut.
89	    ///
90	    /// It does not set the rows: the response holds TOON [`Value`] rows, not the caller's `T`, so pass `outcome.kept`
91	    /// (converted to rows) to [`items`](Self::items) yourself. Later [`total_count`](Self::total_count) or
92	    /// [`hints`](Self::hints) calls still override what this sets.
93	    ///
94	    /// ```
95	    /// use michi_core::toon::Value;
96	    /// use michi_core::{truncate_by_count, AgentResponse, OutputFormat};
97	    ///
98	    /// let outcome = truncate_by_count(vec![1, 2, 3, 4], 2);
99	    /// let rows = outcome.kept.iter().map(|n| vec![Value::Int(*n)]).collect();
100	    /// let r = AgentResponse::new("issues").items(rows, &["n"]).truncation(&outcome, "pass --limit 4");
101	    /// assert_eq!(
102	    ///     r.render(OutputFormat::Text),
103	    ///     "issues[2]{n}:\n  1\n  2\ntotalCount: 4\nhelp[1]: showing 2 of 4; pass --limit 4"
104	    /// );
105	    /// ```
106	    #[must_use]
107	    pub fn truncation<T>(
108	        mut self,
109	        outcome: &crate::truncation::TruncationOutcome<T>,
110	        guidance: impl Into<String>,
111	    ) -> Self {
112	        self.toon.total_count = Some(outcome.total_before);
113	        if let Some(hint) = outcome.hint(guidance) {
114	            self.hints.push(hint);
115	        }
116	        self
117	    }
118	
119	    /// Populate the KV single-item path.
120	    #[must_use]
121	    pub fn kv_items(mut self, items: Vec<KvItem>) -> Self {
122	        self.single_item = items;
123	        self.target = RenderTarget::Kv;
124	        self
125	    }
126	
127	    /// Append a section. Sections render in insertion order after the `items()` / `kv_items()` slot, if one was set;
128	    /// the caller owns ordering. A response with no section, or one section and no `items()` / `kv_items()`, renders
129	    /// exactly as the sugar for that section would.
130	    ///
131	    /// The response's cell cap ([`truncate_cells_at`](Self::truncate_cells_at)) and truncation hint apply to every
132	    /// `Toon` body. A section's `totalCount` comes from [`Section::total_count`], not from the response's.
133	    #[must_use]
134	    pub fn section(mut self, section: Section) -> Self {
135	        self.sections.push(section);
136	        self
137	    }
138	
139	    /// Attach the response-level budget report; one per response, a second call replaces the first. It renders as a
140	    /// `budget:` block after the last section (see [`BudgetSummary`] for what it carries), and the per-section
141	    /// roll-up appears only when the response renders two or more blocks, counting the `items()` / `kv_items()` slot
142	    /// as one when it has content. michi renders the report; it never computes it.
143	    ///
144	    /// A response with a budget or provenance but no `items()` / `kv_items()` call has no body of its own: the empty
145	    /// `type: []` line that an untouched response renders is left out, as it is when sections are present.
146	    #[must_use]
147	    pub fn budget(mut self, budget: BudgetSummary) -> Self {
148	        self.budget = Some(budget);
149	        self
150	    }
151	
152	    /// Attach the response-level provenance block; one per response, a second call replaces the first. It renders as
153	    /// a `provenance:` block after `budget:` (see [`ProvenanceBlock`]).
154	    #[must_use]
155	    pub fn provenance(mut self, provenance: ProvenanceBlock) -> Self {
156	        self.provenance = Some(provenance);
157	        self
158	    }
159	
160	    /// Append a contextual hint.
161	    #[must_use]
162	    pub fn hint(mut self, hint: impl Into<String>) -> Self {
163	        self.hints.push(Hint::new(hint));
164	        self
165	    }
166	
167	    /// Replace all contextual hints.
168	    #[must_use]
169	    pub fn hints(mut self, hints: Vec<Hint>) -> Self {
170	        self.hints = hints;
171	        self
172	    }
173	
174	    /// Append a recovery hint.
175	    #[must_use]
176	    pub fn recovery_hint(mut self, r: RecoveryHint) -> Self {
177	        self.recovery.push(r);
178	        self
179	    }
180	
181	    /// Set the max string cell length, in chars, before truncation on the TOON path. Default:
182	    /// [`DEFAULT_TRUNCATE_CELLS`].
183	    ///
184	    /// The limit counts characters before TOON escaping and quoting, so a cell that needs quotes or escapes is
185	    /// written longer than `limit` (see [`crate::toon::ToonOptions::max_cell_len`]). The KV path is never truncated.
186	    #[must_use]
187	    pub fn truncate_cells_at(mut self, limit: usize) -> Self {
188	        self.toon.max_cell_len = limit;
189	        self
190	    }
191	
192	    /// Set the caller's instruction for getting a cut TOON cell in full. When a cell was cut, michi adds one line to
193	    /// `help[]` (after your own hints) that names the `truncated` block and this instruction (see
194	    /// [`crate::toon::ToonOptions::truncation_hint`]). Unset by default: michi never invents a parameter the tool
195	    /// may not have, and the `truncated` block still reports each cut. Pass tool-author text, never data.
196	    #[must_use]
197	    pub fn truncation_hint(mut self, hint: impl Into<String>) -> Self {
198	        self.toon.truncation_hint = Some(hint.into());
199	        self
200	    }
201	
202	    /// Mark this response as an error state.
203	    #[must_use]
204	    pub fn as_error(mut self) -> Self {
205	        self.is_error = true;
206	        self
207	    }
208	
209	    /// Attach a human-facing companion block (`audience: user`).
210	    #[must_use]
211	    pub fn human_content(mut self, text: impl Into<String>) -> Self {
212	        self.human_content = Some(text.into());
213	        self
214	    }
215	
216	    /// The TOON body, and whether it is a validation-failure error block instead of the requested rows.
217	    ///
218	    /// The third item is the `help[]` line michi adds when it cut a cell and a truncation hint is set.
219	    fn toon_body(&self) -> (String, bool, Option<Hint>) {
220	        match self.toon.validate() {
221	            Ok(doc) => {
222	                let (body, _, extra) = doc.render_parts(true);
223	                (body, false, extra.map(Hint::new))
224	            }
225	            Err(e) => (validation_error_body("toon_validation_failed", &e.to_string()), true, None),
226	        }
227	    }
228	
229	    /// The caller's hints, then michi's own truncation line when there is one: a single `help` block.
230	    fn hints_with<'a>(&'a self, extra: &[Hint]) -> std::borrow::Cow<'a, [Hint]> {
231	        if extra.is_empty() {
232	            std::borrow::Cow::Borrowed(&self.hints)
233	        } else {
234	            let mut all = Vec::with_capacity(self.hints.len() + extra.len());
235	            all.extend(self.hints.iter().cloned());
236	            all.extend(extra.iter().cloned());
237	            std::borrow::Cow::Owned(all)
238	        }
239	    }
240	
241	    /// The options a `Toon` section renders by: the response's cell cap and truncation hint, the section's own
242	    /// `totalCount` rule. Copies the rows, which the single-slot path avoids by rendering its options in place.
243	    fn section_options(
244	        &self,
245	        name: &str,
246	        fields: &[String],
247	        rows: &[Vec<Value>],
248	        shown_total: Option<usize>,
249	    ) -> crate::toon::ToonOptions {
250	        let mut opts = crate::toon::ToonOptions::new(name, fields.to_vec(), rows.to_vec());
251	        opts.total_count = shown_total;
252	        opts.max_cell_len = self.toon.max_cell_len;
253	        opts.truncation_hint.clone_from(&self.toon.truncation_hint);
254	        opts
255	    }
256	
257	    /// The KV body, and whether it is a validation-failure error block instead of the requested items (a duplicate
258	    /// or reserved key, see [`crate::kv::KvError`]).
259	    fn kv_body(&self) -> (String, bool) {
260	        // `render_kv` renders nothing for no items, dropping the count; a response that set one still reports it,
261	        // as the TOON path does (`t: []\ntotalCount: 0`).
262	        if self.single_item.is_empty() {
263	            let body = self.toon.total_count.map_or_else(String::new, |n| format!("totalCount: {n}"));
264	            return (body, false);
265	        }
266	        match crate::kv::render_kv(&self.single_item, self.toon.total_count, &[]) {
267	            Ok(body) => (body, false),
268	            Err(e) => (validation_error_body("kv_validation_failed", &e.to_string()), true),
269	        }
270	    }
271	
272	    /// Whether the response uses any envelope slot (sections, budget or provenance). Without one it renders exactly
273	    /// as it did before the envelope existed.
274	    fn has_envelope(&self) -> bool {
275	        !self.sections.is_empty() || self.budget.is_some() || self.provenance.is_some()
276	    }
277	
278	    /// The `items()` / `kv_items()` slot as an envelope part.
279	    fn slot_part(&self) -> (Part<'_>, bool, Option<Hint>) {
280	        match self.target {
281	            RenderTarget::Toon | RenderTarget::Unset => match self.toon.validate() {
282	                Ok(doc) => {
283	                    let (text, cuts, extra) = doc.render_parts(false);
284	                    let name = self.toon.type_name.as_str();
285	                    (Part { name, text, cuts, total: self.toon.total_count }, false, extra.map(Hint::new))
286	                }
287	                Err(e) => (Part::failed(&self.toon.type_name, "toon_validation_failed", &e.to_string()), true, None),
288	            },
289	            RenderTarget::Kv => kv_part(&self.toon.type_name, &self.single_item, self.toon.total_count),
290	        }
291	    }
292	
293	    /// One section as an envelope part.
294	    fn section_part<'a>(&self, s: &'a Section) -> (Part<'a>, bool, Option<Hint>) {
295	        let total = s.shown_total();
296	        match &s.body {
297	            SectionBody::Toon { fields, rows } => match self.section_options(&s.name, fields, rows, total).validate() {
298	                Ok(doc) => {
299	                    let (text, cuts, extra) = doc.render_parts(false);
300	                    (Part { name: &s.name, text, cuts, total }, false, extra.map(Hint::new))
301	                }
302	                Err(e) => (Part::failed(&s.name, "toon_validation_failed", &e.to_string()), true, None),
303	            },
304	            SectionBody::Kv(items) => kv_part(&s.name, items, total),
305	            SectionBody::Text(text) => {
306	                (Part { name: &s.name, text: text.clone(), cuts: Vec::new(), total: None }, false, None)
307	            }
308	        }
309	    }
310	
311	    /// The body for a response that uses the envelope: slot (if used), sections, `budget:`, `provenance:`.
312	    ///
313	    /// Blocks are joined with one LF and empty ones are skipped. `truncated` and `totalCount` are root keys, so they
314	    /// may appear once: when one block has them they stay inline where the single-slot render puts them; when two or
315	    /// more do, each becomes one table with a leading `section` column, after the last block.
316	    fn envelope_body<'a>(&'a self) -> (String, bool, Vec<Hint>) {
317	        let mut parts: Vec<Part<'a>> = Vec::with_capacity(self.sections.len() + 1);
318	        let mut failed = false;
319	        let mut extras: Vec<Hint> = Vec::new();
320	        let mut note = |(part, part_failed, extra): (Part<'a>, bool, Option<Hint>)| {
321	            failed |= part_failed;
322	            // One line per cut response is enough: every section's line says the same thing.
323	            if let Some(h) = extra {
324	                if !extras.contains(&h) {
325	                    extras.push(h);
326	                }
327	            }
328	            part
329	        };
330	        let mut slot_has_content = false;
331	        // An untouched `items()` / `kv_items()` slot has no body of its own to put before the envelope.
332	        if self.target != RenderTarget::Unset {
333	            let part = note(self.slot_part());
334	            slot_has_content = !part.text.is_empty() || part.total.is_some();
335	            parts.push(part);
336	        }
337	        for s in &self.sections {
338	            parts.push(note(self.section_part(s)));
339	        }
340	        let cutters = parts.iter().filter(|p| !p.cuts.is_empty()).count();
341	        let totals = parts.iter().filter(|p| p.total.is_some()).count();
342	        let mut out = String::with_capacity(parts.iter().map(|p| p.text.len() + 24).sum::<usize>() + 256);
343	        for p in &parts {
344	            join_block(&mut out, &p.text);
345	            if cutters == 1 && !p.cuts.is_empty() {
346	                join_block(&mut out, &truncated_table(std::slice::from_ref(p)));
347	            }
348	            if let (1, Some(n)) = (totals, p.total) {
349	                join_block(&mut out, &format!("totalCount: {n}"));
350	            }
351	        }
352	        if cutters >= 2 {
353	            join_block(&mut out, &truncated_table(&parts));
354	        }
355	        if totals >= 2 {
356	            join_block(&mut out, &total_table(&parts));
357	        }
358	        if let Some(b) = &self.budget {
359	            let blocks = self.sections.len() + usize::from(slot_has_content);
360	            join_block(&mut out, &crate::budget::render_budget_block(b, blocks >= 2));
361	        }
362	        if let Some(p) = &self.provenance {
363	            join_block(&mut out, &crate::provenance::render_provenance_block(p));
364	        }
365	        (out, failed || self.is_error, extras)
366	    }
367	
368	    /// The selected body, and whether this response is an error: set by `as_error()` or by a body that failed
369	    /// validation. Every output surface reads its error flag from here so text, JSON and MCP never disagree.
370	    fn body(&self) -> (String, bool, Vec<Hint>) {
371	        if self.has_envelope() {
372	            return self.envelope_body();
373	        }
374	        let (body, failed, extra) = match self.target {
375	            RenderTarget::Toon | RenderTarget::Unset => self.toon_body(),
376	            RenderTarget::Kv => {
377	                let (body, failed) = self.kv_body();
378	                (body, failed, None)
379	            }
380	        };
381	        (body, failed || self.is_error, extra.into_iter().collect())
382	    }
383	
384	    /// Compose the text document: body, help block, recovery block. Each part is a TOON 4.4 document without a
385	    /// trailing newline and the append helpers join them with one LF, so the result is one root object whose keys
386	    /// are unique (the body cannot use `totalCount`, `help`, `recovery` or `truncated`). Appends to `body` in place.
387	    fn finish_text(&self, mut body: String, extra: &[Hint]) -> String {
388	        let hints = self.hints_with(extra);
389	        if !hints.is_empty() || !self.recovery.is_empty() {
390	            body.reserve(1 + hints.len() * 60 + self.recovery.len() * 80);
391	        }
392	        crate::hints::append_hints(&mut body, &hints);
393	        crate::recovery::append_recovery(&mut body, &self.recovery);
394	        body
395	    }
396	
397	    /// Render the response in the requested format.
398	    #[must_use]
399	    pub fn render(&self, format: OutputFormat) -> String {
400	        match format {
401	            OutputFormat::Text => self.render_text(),
402	            OutputFormat::Json => self.render_json(),
403	        }
404	    }
405	
406	    /// Render via the TOON path.
407	    #[must_use]
408	    pub fn render_toon(&self) -> String {
409	        let (body, _, extra) = self.toon_body();
410	        self.finish_text(body, extra.as_slice())
411	    }
412	
413	    /// Render via the KV path.
414	    #[must_use]
415	    pub fn render_kv(&self) -> String {
416	        self.finish_text(self.kv_body().0, &[])
417	    }
418	
419	    fn render_text(&self) -> String {
420	        let (body, _, extra) = self.body();
421	        self.finish_text(body, &extra)
422	    }
423	
424	    /// Whether this response is an error: `as_error()` was called, or the TOON rows or KV items failed validation and
425	    /// the body is a `toon_validation_failed` or `kv_validation_failed` error block. Validates without rendering.
426	    #[must_use]
427	    pub fn is_error(&self) -> bool {
428	        let slot_failed = match self.target {
429	            RenderTarget::Toon | RenderTarget::Unset => self.toon.validate().is_err(),
430	            RenderTarget::Kv => crate::kv::validate_keys(&self.single_item).is_err(),
431	        };
432	        if !self.has_envelope() {
433	            return self.is_error || slot_failed;
434	        }
435	        self.is_error
436	            || (slot_failed && self.target != RenderTarget::Unset)
437	            || self.sections.iter().any(|s| match &s.body {
438	                SectionBody::Toon { fields, rows } => {
439	                    self.section_options(&s.name, fields, rows, s.shown_total()).validate().is_err()
440	                }
441	                SectionBody::Kv(items) => crate::kv::validate_keys(items).is_err(),
442	                SectionBody::Text(_) => false,
443	            })
444	    }
