490	    fn json_from_body(&self, body: &str, is_error: bool, extra: &[Hint]) -> String {
491	        let hints = self.hints_with(extra);
492	        let capacity =
493	            body.len() + hints.iter().map(|h| h.as_str().len() + 16).sum::<usize>() + self.recovery.len() * 64 + 64;
494	        let mut out = String::with_capacity(capacity + if self.has_envelope() { body.len() + 128 } else { 0 });
495	        out.push_str("{\"body\":");
496	        json_string(&mut out, body);
497	        if !self.sections.is_empty() {
498	            out.push_str(",\"sections\":[");
499	            for (i, s) in self.sections.iter().enumerate() {
500	                if i > 0 {
501	                    out.push(',');
502	                }
503	                push_section_json(&mut out, s);
504	            }
505	            out.push(']');
506	        }
507	        if let Some(b) = &self.budget {
508	            out.push_str(",\"budget\":");
509	            out.push_str(&crate::budget::budget_json(b));
510	        }
511	        if let Some(p) = &self.provenance {
512	            out.push_str(",\"provenance\":");
513	            out.push_str(&crate::provenance::provenance_json(p));
514	        }
515	        out.push_str(",\"hints\":[");
516	        for (i, h) in hints.iter().enumerate() {
517	            if i > 0 {
518	                out.push(',');
519	            }
520	            json_string(&mut out, h.as_str());
521	        }
522	        out.push_str("],\"recovery\":[");
523	        for (i, r) in self.recovery.iter().enumerate() {
524	            if i > 0 {
525	                out.push(',');
526	            }
527	            out.push_str("{\"tool\":");
528	            json_string(&mut out, &r.tool);
529	            out.push_str(",\"params\":");
530	            crate::recovery::push_params_json(&mut out, &r.params);
531	            if let Some(reason) = &r.reason {
532	                out.push_str(",\"reason\":");
533	                json_string(&mut out, reason);
534	            }
535	            out.push('}');
536	        }
537	        out.push_str("],\"isError\":");
538	        out.push_str(if is_error { "true" } else { "false" });
539	        out.push('}');
540	        out
541	    }
542	}
