544	/// The body that replaces rows or items that cannot form a valid document: `error: <code>` and the quoted message.
545	fn validation_error_body(code: &str, message: &str) -> String {
546	    let message = crate::toon::escape_value(message);
547	    let mut out = String::with_capacity(17 + code.len() + message.len());
548	    out.push_str("error: ");
549	    out.push_str(code);
550	    out.push_str("\nmessage: ");
551	    out.push_str(&message);
552	    out
553	}
