555	/// One block of an envelope body before the root-level `truncated` and `totalCount` keys are placed.
556	struct Part<'a> {
557	    /// The block's name, the `section` column when several blocks share a root key.
558	    name: &'a str,
559	    /// The block's text without its `truncated` block or `totalCount` line.
560	    text: String,
561	    /// Cut cells as `(row, field name, chars removed)`.
562	    cuts: Vec<(usize, String, usize)>,
563	    /// The `totalCount` this block reports, when it reports one.
564	    total: Option<usize>,
565	}
566	
567	impl<'a> Part<'a> {
568	    /// A block that failed validation: the error body replaces its content and it reports no count.
569	    fn failed(name: &'a str, code: &str, message: &str) -> Self {
570	        Self { name, text: validation_error_body(code, message), cuts: Vec::new(), total: None }
571	    }
572	}
573	
574	/// A KV block as a part. No items still reports a count the caller set, as the single-slot render does.
575	fn kv_part<'a>(name: &'a str, items: &[KvItem], total: Option<usize>) -> (Part<'a>, bool, Option<Hint>) {
576	    if items.is_empty() {
577	        return (Part { name, text: String::new(), cuts: Vec::new(), total }, false, None);
578	    }
579	    match crate::kv::render_kv(items, None, &[]) {
580	        Ok(text) => (Part { name, text, cuts: Vec::new(), total }, false, None),
581	        Err(e) => (Part::failed(name, "kv_validation_failed", &e.to_string()), true, None),
582	    }
583	}
584	
585	/// Append `block` after a LF unless either side is empty.
586	fn join_block(out: &mut String, block: &str) {
587	    if block.is_empty() {
588	        return;
589	    }
590	    if !out.is_empty() {
591	        out.push('\n');
592	    }
593	    out.push_str(block);
594	}
595	
596	/// The `truncated` block for the cuts of `parts`. A single block uses the shape the single-slot render has
597	/// (`{row,field,removed}`); several share one table with a leading `section` column.
598	fn truncated_table(parts: &[Part<'_>]) -> String {
599	    use std::fmt::Write as _;
600	    let n: usize = parts.iter().map(|p| p.cuts.len()).sum();
601	    let mut out = String::with_capacity(48 + n * 32);
602	    let multi = parts.iter().filter(|p| !p.cuts.is_empty()).count() > 1;
603	    let _ = write!(out, "truncated[{n}]{}:", if multi { "{section,row,field,removed}" } else { "{row,field,removed}" });
604	    for p in parts {
605	        for (row, field, removed) in &p.cuts {
606	            out.push_str("\n  ");
607	            if multi {
608	                out.push_str(&crate::toon::escape_value(p.name));
609	                out.push(',');
610	            }
611	            let _ = write!(out, "{row},{},{removed}", crate::toon::escape_value(field));
612	        }
613	    }
614	    out
615	}
616	
617	/// The merged `totalCount[N]{section,total}:` table, for two or more blocks that report a total.
618	fn total_table(parts: &[Part<'_>]) -> String {
619	    use std::fmt::Write as _;
620	    let n = parts.iter().filter(|p| p.total.is_some()).count();
621	    let mut out = String::with_capacity(32 + n * 24);
622	    let _ = write!(out, "totalCount[{n}]{{section,total}}:");
623	    for p in parts {
624	        if let Some(total) = p.total {
625	            let _ = write!(out, "\n  {},{total}", crate::toon::escape_value(p.name));
626	        }
627	    }
628	    out
629	}
