631	/// A TOON cell value as JSON. Non-finite floats are `null`, as in the text render.
632	fn push_value_json(out: &mut String, v: &Value) {
633	    use std::fmt::Write as _;
634	    match v {
635	        Value::Str(s) => json_string(out, s),
636	        Value::Int(n) => {
637	            let _ = write!(out, "{n}");
638	        }
639	        Value::UInt(n) => {
640	            let _ = write!(out, "{n}");
641	        }
642	        Value::Float(f) => crate::toon::push_f64(out, *f),
643	        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
644	        _ => out.push_str("null"),
645	    }
646	}
647	
648	/// One section as the JSON object spec 07 section 5 describes. Rows carry the full values: the per-cell cap shapes
649	/// the text render, and `structuredContent` is the typed copy of the same data.
650	fn push_section_json(out: &mut String, s: &Section) {
651	    use std::fmt::Write as _;
652	    out.push_str("{\"name\":");
653	    json_string(out, &s.name);
654	    match &s.body {
655	        SectionBody::Toon { fields, rows } => {
656	            out.push_str(",\"kind\":\"toon\",\"fields\":[");
657	            for (i, f) in fields.iter().enumerate() {
658	                if i > 0 {
659	                    out.push(',');
660	                }
661	                json_string(out, f);
662	            }
663	            out.push_str("],\"rows\":[");
664	            for (i, row) in rows.iter().enumerate() {
665	                if i > 0 {
666	                    out.push(',');
667	                }
668	                out.push('[');
669	                for (j, cell) in row.iter().enumerate() {
670	                    if j > 0 {
671	                        out.push(',');
672	                    }
673	                    push_value_json(out, cell);
674	                }
675	                out.push(']');
676	            }
677	            out.push(']');
678	        }
679	        SectionBody::Kv(items) => {
680	            out.push_str(",\"kind\":\"kv\",\"items\":[");
681	            for (i, item) in items.iter().enumerate() {
682	                if i > 0 {
683	                    out.push(',');
684	                }
685	                out.push_str("{\"key\":");
686	                json_string(out, &item.key);
687	                out.push_str(",\"value\":");
688	                crate::kv::kv_value_to_json(out, &item.value);
689	                out.push('}');
690	            }
691	            out.push(']');
692	        }
693	        SectionBody::Text(text) => {
694	            out.push_str(",\"kind\":\"text\",\"text\":");
695	            json_string(out, text);
696	        }
697	    }
698	    let _ = write!(out, ",\"returnedCount\":{}", s.count());
699	    if let Some(total) = s.total_count {
700	        let _ = write!(out, ",\"totalCount\":{total}");
701	    }
702	    out.push_str(",\"truncated\":");
703	    out.push_str(if s.truncated { "true" } else { "false" });
704	    out.push('}');
705	}
706	
707	fn json_string(out: &mut String, s: &str) {
708	    crate::kv::json_escape_str(out, s);
709	}
